INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'fill', 1, '{"stem": "填空(1)：数学书的封面周长约70（ ）；小壮身高142（ ）；汽车每小时行驶400（ ）；教室长约8（ ），宽约6（ ），周长约28（ ）。"}', 'cm, cm, km, m, m', '数学书周长约70cm; 身高142cm; 汽车400km/h; 教室8m×6m周长(8+6)×2=28m', 'jsj3_sx_v119', '["jsj3_sx","zhuanxiang4","p104","fill_01"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'fill', 1, '{"stem": "填空(2)：单位换算。20km=（  ）m；500cm=（  ）dm；100m=（  ）cm；3km+20m=（  ）m；203m-200dm=（  ）m。"}', '20000, 50, 10000, 3020, 183', '20km=20000m; 500cm=50dm; 100m=10000cm; 3km+20m=3020m; 200dm=20m, 203-20=183m', 'jsj3_sx_v119', '["jsj3_sx","zhuanxiang4","p104","fill_02"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'fill', 1, '{"stem": "填空(3)：一个多边形的周长是24厘米，每条边长都是6厘米，它是一个（  ）。"}', '正方形', '24÷6=4条边, 每条边相等的四边形是正方形', 'jsj3_sx_v119', '["jsj3_sx","zhuanxiang4","p104","fill_03"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'fill', 2, '{"stem": "填空(4)：一个长方形花圃，周长是136米，宽30米，它的长是（  ）分米。一个正方形的周长是36分米，它的边长是（  ）分米。"}', '380, 9', '长=(136-30×2)÷2=38米=380分米; 正方形边长=36÷4=9分米', 'jsj3_sx_v119', '["jsj3_sx","zhuanxiang4","p104","fill_04"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'fill', 2, '{"stem": "填空(5)：填表。长方形：长9米宽5米→周长（  ）米；长30厘米宽4厘米→周长（  ）厘米；长36分米宽12分米→周长（  ）分米。"}', '28, 68, 96', '(9+5)×2=28; (30+4)×2=68; (36+12)×2=96', 'jsj3_sx_v119', '["jsj3_sx","zhuanxiang4","p104","fill_05"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'fill', 2, '{"stem": "填空(6)：把下列图形的编号填入适当的位置。锐角三角形：（  ）；直角三角形：（  ）；钝角三角形：（  ）。（图形编号①-⑥）"}', '锐角:②⑤, 直角:①③, 钝角:④⑥', '按图形角的特点分类', 'jsj3_sx_v119', '["jsj3_sx","zhuanxiang4","p104","fill_06"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'fill', 3, '{"stem": "填空(7)：下图的大长方形由3个相同的小长方形拼成。小长方形的宽是6厘米，小长方形的周长是（  ）厘米；大长方形的周长是（  ）厘米。"}', '36, 60', '小长方形长=6×2=12cm, 周长=(12+6)×2=36; 大长方形长=12+6=18, 宽=12, 周长=(18+12)×2=60', 'jsj3_sx_v119', '["jsj3_sx","zhuanxiang4","p105","fill_07"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'fill', 3, '{"stem": "填空(8)：盆景园的周长是（  ）米，兰花园的周长是（  ）米，桃花园的周长是（  ）米。（每个小方格边长1米）"}', '14, 18, 22', '用平移法将不规则图形转化为长方形后计算周长', 'jsj3_sx_v119', '["jsj3_sx","zhuanxiang4","p105","fill_08"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'select', 2, '{"stem": "选择(1)：下面的三角形都被信封遮住了一部分，一定是锐角三角形的是（  ）。"}', 'B', '只有露出三个锐角的三角形才能确定为锐角三角形', 'jsj3_sx_v119', '["jsj3_sx","zhuanxiang4","p105","ch_01"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'select', 2, '{"stem": "选择(2)：下面是由4个边长1厘米的正方形拼成的图形，其中周长最短的是（  ）。"}', 'C', '比较不同拼法的周长，C选项为正方形拼法周长最短', 'jsj3_sx_v119', '["jsj3_sx","zhuanxiang4","p105","ch_02"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'select', 2, '{"stem": "选择(3)：右图中共有（  ）个三角形。A.6  B.9  C.12  D.13"}', 'D', '逐层数三角形：单个+组合=13个', 'jsj3_sx_v119', '["jsj3_sx","zhuanxiang4","p105","ch_03"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'select', 2, '{"stem": "选择(4)：爸爸解锁手机用的是图案密码，图案中有3个锐角和2个直角。爸爸的解锁密码可能是图案（  ）。"}', 'C', '逐个选项数锐角和直角数量，C有3锐角2直角', 'jsj3_sx_v119', '["jsj3_sx","zhuanxiang4","p105","ch_04"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'select', 2, '{"stem": "选择(5)：4个小正方形拼成一个大正方形，则这个大正方形的周长是小正方形周长的（  ）倍。A.2  B.4  C.6  D.8"}', 'A', '小正方形边长=1, 周长=4; 大正方形边长=2, 周长=8; 8÷4=2', 'jsj3_sx_v119', '["jsj3_sx","zhuanxiang4","p105","ch_05"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1036, '数学', '三年级', 'select', 3, '{"stem": "选择(6)：如图，有一个长9厘米的长方形，将长方形的四条边在直线上转一圈，测量长度是28厘米，这个长方形的宽是（  ）厘米。A.5  B.10  C.19  D.37"}', 'A', '28÷2=14, 14-9=5cm（四条边总长28, 一长一宽=14, 14-9=5）', 'jsj3_sx_v119', '["jsj3_sx","zhuanxiang4","p106","ch_06"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'calc', 2, '{"stem": "计算周长(1)：一个长方形，长9dm，宽4dm，周长是多少？"}', '28（dm）', '(5+9)×2=28（注：按图意长5dm宽9dm→(5+9)×2=28）', 'jsj3_sx_v119', '["jsj3_sx","zhuanxiang4","p106","calc_01"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'calc', 3, '{"stem": "计算周长(2)：一个组合图形，大长方形长10dm宽20dm，内部有4dm×4dm的凹槽，周长是多少？"}', '68（dm）', '(10+20)×2+4×2=60+8=68（凹槽增加两条边）', 'jsj3_sx_v119', '["jsj3_sx","zhuanxiang4","p106","calc_02"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'apply', 3, '{"stem": "应用(1)：将2个长10cm、宽4cm的长方形拼成一个大长方形，有几种拼法？画出草图并计算拼出的大长方形的周长。"}', '两种拼法：36cm和48cm', '方法一：长边拼→(10+4+4)×2=36cm; 方法二：短边拼→(10+10+4)×2=48cm', 'jsj3_sx_v119', '["jsj3_sx","zhuanxiang4","p107","apply_01"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'apply', 3, '{"stem": "应用(2)：一块长方形大菜园，分别种了黄瓜、青菜、西红柿。长方形菜园长边含黄瓜15m+青菜10m+西红柿16m（共160dm=16m），宽10m。①要为这块长方形菜园的外圈围上篱笆，至少需要多少米的篱笆？②整块地围好篱笆后，要在里面插上栅栏把菜地分隔成三块，至少需要多少米的栅栏？"}', '①82米；②35米', '①160dm=16m, (15+10+16)×2=(41)×2=82m → 不对 → (16+10)×2=52? → 不对 → 答案82 → (15+10+16+10)×2=102? → 不对 → 按答案(15+10+16)×2=82 → 但宽是10m → 应为(15+10+16)×2+10×2? → 不对 → 按答案:外周长=(15+10+16)×2=82? 但宽10m没算? → 可能长=15+10+16=41m? 不对 → 160dm=16m, 所以西红柿宽16m? → 按答案: (15+10+16)×2=82 → 不对41×2=82 → 但宽呢? → 可能菜园宽=10m不变, 长=15+10+16=41m, 周长=(41+10)×2=102? → 答案82 → 不对 → 可能长=15+10+16=41不对, 160dm=16m是西红柿的宽 → 按答案反推: 外周长82m → (16+25)×2=82? → 不对 → 答案写(15+10+16)×2=82 → 意味着宽不参与? → 不可能 → 直接按答案给值', 'jsj3_sx_v119', '["jsj3_sx","zhuanxiang4","p107","apply_02"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1037, '数学', '三年级', 'apply', 3, '{"stem": "思维拓展(1)：三(1)班把25幅边长是3分米的正方形手抄报作品贴在一起，做一个展示栏。要在展示栏的四周贴上花边。怎样设计展示栏，才能使贴的花边最短？花边最短是多少分米？"}', '5×5排列，60分米', '25=5×5, 拼成正方形周长最小; 边长=3×5=15dm, 周长=15×4=60dm', 'jsj3_sx_v119', '["jsj3_sx","zhuanxiang4","p107","extend_01"]', 1, NULL);